CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'volunteer', date_of_birth TEXT);
CREATE TABLE IF NOT EXISTS volunteer_profiles (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE, skills TEXT DEFAULT '', interests TEXT DEFAULT '', availability TEXT DEFAULT '', location TEXT DEFAULT '', photo_filename TEXT, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT NOT NULL, required_skills TEXT DEFAULT '', interests TEXT DEFAULT '', availability TEXT DEFAULT '', location TEXT DEFAULT '', image_filename TEXT, organization_id INTEGER, start_date TEXT, end_date TEXT);
CREATE TABLE IF NOT EXISTS applications (id INTEGER PRIMARY KEY AUTOINCREMENT, volunteer_id INTEGER NOT NULL, task_id INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', score REAL NOT NULL DEFAULT 0, FOREIGN KEY(volunteer_id) REFERENCES users(id), FOREIGN KEY(task_id) REFERENCES tasks(id), UNIQUE(volunteer_id, task_id));
